-- 102_project_payment_closeout.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_payment_closeout_versions(id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),contract_value numeric(24,2)NOT NULL CHECK(contract_value>=0),certified_value numeric(24,2)NOT NULL CHECK(certified_value>=0),paid_value numeric(24,2)NOT NULL CHECK(paid_value>=0),retention_held numeric(24,2)NOT NULL CHECK(retention_held>=0),outstanding_value numeric(24,2)NOT NULL CHECK(outstanding_value>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),retention_percentage numeric(8,4),retention_status text,retention_release_condition text NOT NULL DEFAULT'',future_obligations text NOT NULL CHECK(btrim(future_obligations)<>''AND char_length(future_obligations)<=3000),payment_explanation text NOT NULL CHECK(btrim(payment_explanation)<>''AND char_length(payment_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number));
CREATE UNIQUE INDEX IF NOT EXISTS project_payment_closeout_one_confirmed_idx ON public.project_payment_closeout_versions(project_id)WHERE status='CONFIRMED';CREATE OR REPLACE FUNCTION private.prevent_project_payment_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_payment_closeout_immutable ON public.project_payment_closeout_versions;CREATE TRIGGER project_payment_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_payment_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_project_payment_closeout_mutation();
ALTER TABLE public.project_payment_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_payment_closeout_select ON public.project_payment_closeout_versions;CREATE POLICY project_payment_closeout_select ON public.project_payment_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_payment_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_payment_closeout(p_project_id bigint,p_closeout_id uuid,p_future_obligations text,p_payment_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;s public.project_payment_schedules%ROWTYPE;t public.project_payment_retention_terms%ROWTYPE;contract numeric;certified numeric;paid numeric;released numeric;held numeric;outstanding numeric;version_no integer;state text;result jsonb;
BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_future_obligations,''))=''OR char_length(p_future_obligations)>3000 OR btrim(COALESCE(p_payment_explanation,''))=''OR char_length(p_payment_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_PAYMENT_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.payment.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.payment.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_payment_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT*INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id ORDER BY(status='ACTIVE')DESC,version_number DESC LIMIT 1;IF s.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CLOSEOUT_REQUIRES_PAYMENT_SCHEDULE'USING ERRCODE='55000';END IF;SELECT*INTO t FROM public.project_payment_retention_terms WHERE payment_schedule_id=s.id;contract:=s.contract_value;SELECT COALESCE(sum(x.certified_amount),0)INTO certified FROM(SELECT DISTINCT ON(certification_case_id)certification_case_id,certified_amount FROM public.project_payment_certification_decisions WHERE project_id=p_project_id AND decision_type IN('FULL','PARTIAL')ORDER BY certification_case_id,decision_number DESC)x;SELECT COALESCE(sum(amount),0)INTO paid FROM public.project_payment_tracking_events WHERE project_id=p_project_id AND event_type='PAYMENT_RECEIVED';SELECT COALESCE(sum(released_amount),0)INTO released FROM public.project_payment_retention_releases WHERE project_id=p_project_id;held:=greatest(round(certified*COALESCE(t.retention_percentage,0)/100,2)-released,0);outstanding:=greatest(certified-paid,0);
SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_payment_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_payment_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,contract,certified,paid,held,outstanding,s.currency_code,t.retention_percentage,t.status,COALESCE(t.release_condition,''),btrim(p_future_obligations),btrim(p_payment_explanation),u,now());result:=jsonb_build_object('paymentCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'contractValue',contract,'certifiedValue',certified,'paidValue',paid,'retentionHeld',held,'outstandingValue',outstanding,'currencyCode',s.currency_code);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_payment_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_payment_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_payment_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('paymentCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'contractValue',x.contract_value,'certifiedValue',x.certified_value,'paidValue',x.paid_value,'retentionHeld',x.retention_held,'outstandingValue',x.outstanding_value,'currencyCode',x.currency_code,'retentionPercentage',x.retention_percentage,'retentionStatus',x.retention_status,'retentionReleaseCondition',x.retention_release_condition,'futureObligations',x.future_obligations,'paymentExplanation',x.payment_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_project_payment_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_payment_closeout(bigint,uuid,text,text,boolean,uuid),public.get_project_payment_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_payment_closeout(bigint,uuid,text,text,boolean,uuid),public.get_project_payment_closeout(bigint)TO authenticated;COMMIT;
